function migrate(){try{const old=JSON.parse(localStorage.getItem('king-agent-v1'));if(!old||!Array.isArray(old.players)||!Number.isFinite(old.cash))return null;const s=seed(fresh());s.name=old.name||s.name;s.cash=old.cash;s.rep=cap(old.rep||20,0,100);s.week=Math.max(1,Math.min(old.week||1,24));s.actions=cap(old.actions||0,0,3);s.ended=!!old.ended;for(const op of old.players){const p=createPlayer(s);p.name=op.name;p.age=op.age;p.role=op.role;p.club=s.clubs.find(c=>c.name===op.club)?.id??null;p.skill=op.skill;p.potential=Math.max(op.skill,op.potential);p.estimate=p.potential;p.trust=op.trust;p.mandate=s.week+52;s.players.push(p)}if(s.players.length)s.tutorial=1;s.log.unshift({week:s.week,text:'Carriera precedente importata: i mandati ripartono con durata 52 settimane.'});return validSave(s)?s:null}catch{return null}}
function boot(){try{const saved=JSON.parse(localStorage.getItem(KEY));state=validSave(saved)?saved:null}catch{}if(!state)state=migrate()||seed(fresh());$('advance').onclick=advance;$('confirm').onclick=()=>{const fn=modalAction;$('modal').close();modalAction=null;if(fn)fn()};$('cancel').onclick=()=>{$('modal').close();modalAction=null};$('importFile').onchange=e=>{importSave(e.target.files[0]);e.target.value=''};render()}






// Career world: fictional international competition, stories and cash planning.
const baseFresh=fresh,baseWeekly=weekly,baseOffers=renderOffers,baseClubs=renderClubs,baseOffice=renderOffice,baseAgency=renderAgency,baseDetail=playerDetail,baseValid=validSave,baseTransact=transact,baseProgress=progressOffer,baseCare=care;
function ensureWorld(s){if(!s.reputation)s.reputation={reliable:s.rep,negotiator:s.rep,developer:s.rep};if(!s.receivables)s.receivables=[];if(!s.fixtures)s.fixtures=[];if(!s.rivals)s.rivals=[{name:'Atlas Sports',style:'Giovani',rep:48},{name:'Prime Eleven',style:'Grandi contratti',rep:65},{name:'Next Goal',style:'Talenti locali',rep:38}];if(!s.external)s.external=s.clubs.flatMap(c=>Array.from({length:3},(_,i)=>({id:'npc-'+c.id+'-'+i,name:NAMES[rnd(0,11)]+' '+SURNAMES[rnd(0,11)],club:c.id,role:ROLES[i+1],skill:cap(c.prestige+rnd(-12,6),35,90),age:rnd(18,30),agent:s.rivals[(c.id+i)%3].name})));for(const c of s.clubs){if(!c.table)c.table={played:0,points:0,gf:0,ga:0};if(!c.coach)c.coach={name:['Sarti','Alonso','Brun','Sosa'][c.id%4],formation:c.id%2?'4-3-3':'3-5-2',favoured:c.need};}for(const p of [...s.players,...s.market]){if(!p.timeline)p.timeline=[{week:s.week,text:'Profilo entrato nel dossier dell’agenzia.'}];if(!p.story)p.story=p.age<=21?'Il primo grande contratto':p.age>=27?'L’ultima occasione':'La stagione della svolta';if(!p.milestones)p.milestones=[];if(!p.deals)p.deals=0;}return s}
fresh=()=>ensureWorld(baseFresh());
validSave=s=>{if(!baseValid(s))return false;try{if(s.reputation&&['reliable','negotiator','developer'].some(k=>!Number.isFinite(s.reputation[k])||s.reputation[k]<0||s.reputation[k]>100))return false;if(s.receivables&&(!Array.isArray(s.receivables)||s.receivables.some(r=>!r||!Number.isFinite(r.amount)||r.amount<0||!Number.isFinite(r.due)||typeof r.reason!=='string')))return false;if(s.external&&(!Array.isArray(s.external)||s.external.length>200||s.external.some(p=>!p||typeof p.name!=='string'||!Number.isFinite(p.skill)||!ROLES.includes(p.role)||!s.clubs.some(c=>c.id===p.club))))return false;for(const k of ['fixtures','rivals'])if(s[k]&&!Array.isArray(s[k]))return false;if(s.rivals&&s.rivals.some(r=>!r||typeof r.name!=='string'||typeof r.style!=='string'||!Number.isFinite(r.rep)))return false;if(s.clubs.some((c,i)=>c.id!==i))return false;if([...s.players,...s.market].some(p=>p.milestones&&(!Array.isArray(p.milestones)||p.milestones.some(x=>typeof x!=='string'))||p.story&&typeof p.story!=='string'||p.deals!==undefined&&!Number.isFinite(p.deals)))return false;if(s.fixtures&&s.fixtures.some(f=>!f||['season','week','home','away','hg','ag'].some(k=>!Number.isFinite(f[k]))))return false;for(const c of s.clubs){if(c.table&&['played','points','gf','ga'].some(k=>!Number.isFinite(c.table[k])))return false;if(c.coach&&(typeof c.coach.name!=='string'||typeof c.coach.formation!=='string'||!ROLES.includes(c.coach.favoured)))return false}for(const p of [...s.players,...s.market])if(p.timeline&&(!Array.isArray(p.timeline)||p.timeline.some(t=>!t||typeof t.text!=='string'||!Number.isFinite(t.week))))return false;ensureWorld(s);return true}catch{return false}};
function story(p,text){p.timeline=p.timeline||[];p.timeline.unshift({week:state.week,text});p.timeline=p.timeline.slice(0,40)}
function repChange(kind,n){ensureWorld(state);state.reputation[kind]=cap(state.reputation[kind]+n,0,100);state.rep=Math.round((state.reputation.reliable+state.reputation.negotiator+state.reputation.developer)/3)}
transact=(amount,reason)=>{ensureWorld(state);if(amount>0&&reason.startsWith('Commissione ')){const now=Math.ceil(amount*.6);baseTransact(now,reason+' · anticipo 60%');state.receivables.push({amount:amount-now,due:state.week+4,reason:reason+' · saldo 40%'});return}baseTransact(amount,reason)};
care=p=>{const actions=state.actions;baseCare(p);if(state.actions<actions){story(p,'L’agente ha ascoltato le mie preoccupazioni.');save()}};
function clubStrength(c){const squad=state.external.filter(p=>p.club===c.id),average=squad.length?squad.reduce((n,p)=>n+p.skill,0)/squad.length:c.prestige;return(c.prestige+average)/2}
function playRound(){const w=weekOfYear();if(w<11||w>24)return;const round=w-11;if(state.fixtures.some(f=>f.season===state.season&&f.week===state.week))return;const ring=state.clubs.map(c=>c.id);for(let i=0;i<round%7;i++)ring.splice(1,0,ring.pop());for(let i=0;i<4;i++){let home=ring[i],away=ring[7-i];if(round>=7)[home,away]=[away,home];const a=state.clubs.find(c=>c.id===home),b=state.clubs.find(c=>c.id===away);const hg=cap(rnd(0,3)+(clubStrength(a)-clubStrength(b)>15?1:0),0,5),ag=cap(rnd(0,3)+(clubStrength(b)-clubStrength(a)>20?1:0),0,5);a.table.played++;b.table.played++;a.table.gf+=hg;a.table.ga+=ag;b.table.gf+=ag;b.table.ga+=hg;if(hg===ag){a.table.points++;b.table.points++}else(hg>ag?a:b).table.points+=3;state.fixtures.unshift({season:state.season,week:state.week,home,away,hg,ag});}state.fixtures=state.fixtures.slice(0,224)}
function standings(){return [...state.clubs].sort((a,b)=>b.table.points-a.table.points||(b.table.gf-b.table.ga)-(a.table.gf-a.table.ga)||b.table.gf-a.table.gf)}
weekly=()=>{ensureWorld(state);if(state.ended)return;const previous=state.players.map(p=>({id:p.id,skill:p.skill,trust:p.trust,club:p.club,matches:p.stats?.matches||0})),oldSeason=state.season;const due=state.receivables.filter(r=>r.due<=state.week+1);for(const r of due)baseTransact(r.amount,r.reason);state.receivables=state.receivables.filter(r=>r.due>state.week+1);if(weekOfYear()===52){const table=standings();if(table[0].table.played){log('Titolo della King League: '+table[0].name+'.');for(const c of state.clubs){const rank=table.findIndex(x=>x.id===c.id);c.base=Math.round(c.base*(rank<3?1.12:.96));c.prestige=cap(c.prestige+(rank<3?3:-1),25,95);}for(const c of state.clubs)c.table={played:0,points:0,gf:0,ga:0};}}
baseWeekly();if(state.season!==oldSeason)for(const p of state.external){p.age++;p.skill=cap(p.skill+(p.age<=23?rnd(0,3):p.age>30?-1:0),30,95)}playRound();for(const p of state.players){ensureWorld(state);const before=previous.find(q=>q.id===p.id);if(before&&p.skill>before.skill){repChange('developer',1);story(p,'Sono cresciuto: qualità '+before.skill+' → '+p.skill+'.')}if(before&&p.trust<before.trust-10){repChange('reliable',-2);story(p,'Una promessa o una richiesta non rispettata ha danneggiato il rapporto.')}if((p.stats?.matches||0)>=10&&!p.milestones.includes('10-presenze')){p.milestones.push('10-presenze');story(p,'Prime 10 presenze nella carriera seguita dall’agenzia.');repChange('developer',2)}if(p.trust>=90&&state.week%10===0){const prospect=createPlayer();prospect.timeline=[{week:state.week,text:'Presentato da '+p.name+'.'}];state.market.push(prospect);log(p.name+' ti presenta un nuovo talento: '+prospect.name+'.')}const c=state.clubs.find(c=>c.id===p.club);if(c&&state.week%9===0){const competition=state.external.filter(q=>q.club===c.id&&q.role===p.role&&q.skill>p.skill).length;p.minutes=cap(p.minutes+(c.coach.favoured===p.role?5:-3)-competition*3,10,90);}}
if(state.week%13===0&&!state.ended){const c=state.clubs[rnd(0,7)];c.coach={name:['Vega','Rossi','Dupont','Molina'][rnd(0,3)],formation:rnd(0,1)?'4-3-3':'3-5-2',favoured:ROLES[rnd(0,3)]};c.need=c.coach.favoured;log('Nuovo allenatore a '+c.name+': '+c.coach.name+', '+c.coach.formation+'. Cambiano le priorità di mercato.');for(const p of state.players.filter(p=>p.club===c.id))story(p,'Cambio allenatore: il nuovo progetto predilige '+c.need+'.');}if(state.week%6===0&&state.external.length){const npc=state.external[rnd(0,state.external.length-1)],destination=state.clubs[rnd(0,7)],fee=Math.round(npc.skill*npc.skill*40);if(npc.club!==destination.id&&destination.budget>=fee){state.clubs[npc.club].budget+=fee;destination.budget-=fee;npc.club=destination.id;}log(npc.agent+' conclude un’operazione per '+npc.name+'. Il mercato si muove anche senza di te.');}render()};
const oldPlayerFit=playerFit;playerFit=(p,c,o)=>{ensureWorld(state);return cap(oldPlayerFit(p,c,o)+(state.reputation.reliable-30)/8,5,95)};
const oldOfferChance=offerChance;offerChance=(p,c,o)=>{ensureWorld(state);return cap(oldOfferChance(p,c,o)+(state.reputation.negotiator-30)/10,10,95)};
progressOffer=o=>{const p=offerPlayer(o),stage=o.stage;const originalAsk=ask;ask=(title,body,fn)=>originalAsk(title,body,()=>{const deals=state.history.length;fn();if(p){if(state.history.length>deals){p.deals=(p.deals||0)+1;story(p,'Contratto concluso con '+clubOf(p)+'. Commissione incassata a rate.');repChange('negotiator',3);repChange('reliable',1);}else if(!state.offers.some(q=>q.id===o.id)){story(p,stage===2?'Ho rifiutato la destinazione: non rispettava le mie priorità.':'La trattativa non è andata a buon fine.');}render();}});try{baseProgress(o)}finally{ask=originalAsk}};
function forecast(){let balance=state.cash;const result=[];for(let i=1;i<=8;i++){const week=state.week+i,income=state.receivables.filter(r=>r.due===week).reduce((n,r)=>n+r.amount,0)+state.sponsors.filter(s=>s.until>=week).reduce((n,s)=>n+s.weekly,0);balance+=income-expenses();result.push({week,income,cost:expenses(),balance})}return result}
function table(headers,rows){const scroll=el('div',undefined,'table-scroll'),t=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');for(const h of headers){const th=el('th',h);th.scope='col';hr.append(th)}head.append(hr);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(let i=0;i<row.length;i++){const td=el('td',String(row[i]));td.setAttribute('data-label',headers[i]);tr.append(td);}body.append(tr)}t.append(head,body);scroll.append(t);return scroll}
function reputationPanel(){ensureWorld(state);const d=el('section',undefined,'panel');d.append(el('h2','Come ti vede il mercato'));for(const [k,label]of [['reliable','Affidabilità'],['negotiator','Capacità negoziale'],['developer','Sviluppo carriere']])d.append(el('p',label+': '+state.reputation[k]+'/100'));d.append(el('p','Promesse e rapporti influenzano l’affidabilità; gli accordi la capacità negoziale; la crescita degli assistiti lo sviluppo.','rules'));return d}
renderOffice=c=>{ensureWorld(state);baseOffice(c);c.append(reputationPanel(),el('h2','La King League'),el('p','Competizione internazionale inventata: 8 club, 14 giornate nelle settimane 11–24.'));c.append(table(['Club','G','Pt','DR'],standings().map(c=>[c.name,c.table.played,c.table.points,c.table.gf-c.table.ga])));const recent=state.fixtures.filter(f=>f.week===state.week);for(const f of recent)c.append(el('p',state.clubs[f.home].name+' '+f.hg+'–'+f.ag+' '+state.clubs[f.away].name))};
function compareDestinations(p){const rows=state.clubs.filter(c=>c.id!==p.club).map(c=>{const competition=state.external.filter(n=>n.club===c.id&&n.role===p.role&&n.skill>p.skill).length;const minutes=cap((c.need===p.role?75:40)-competition*10,10,85),salary=Math.round(p.salary*(c.prestige>65?1.4:1.15)),o={salary,minutes,bonus:0};return{c,minutes,salary,fit:playerFit(p,c,o),competition,growth:p.age<=24&&minutes>=50?'Favorevole':'Limitata'}}).sort((a,b)=>b.fit-a.fit);return rows}
function comparisonDialog(p){const d=el('div');d.append(el('p','Stime orientative, non offerte garantite. Priorità del giocatore: '+p.goal+'.'),table(['Club','Stipendio/sett.','Spazio','Gradimento','Crescita'],compareDestinations(p).map(r=>[r.c.name,money(r.salary),r.minutes+'%',Math.round(r.fit)+'%',r.growth])));ask('Confronta destinazioni · '+p.name,d,()=>{});$('confirm').textContent='Chiudi'}
playerDetail=p=>{ensureWorld(state);baseDetail(p);const box=$('modalBody');box.append(el('h3',p.story),el('p','Accordi conclusi insieme: '+p.deals),btn('Confronta destinazioni',()=>comparisonDialog(p)),el('h3','La sua storia'));for(const item of p.timeline.slice(0,12))box.append(el('p','S'+item.week+' · '+item.text))};
renderClubs=c=>{ensureWorld(state);baseClubs(c);c.append(el('h2','Progetti sportivi'));for(const club of state.clubs)c.append(el('p',club.name+' · mister '+club.coach.name+' · '+club.coach.formation+' · priorità '+club.coach.favoured));c.append(el('h2','Concorrenza sul mercato'));for(const r of state.rivals)c.append(el('p',r.name+' · '+r.style+' · reputazione '+r.rep));c.append(table(['Giocatore','Club','Ruolo','Qualità','Agente'],state.external.map(p=>[p.name,state.clubs.find(c=>c.id===p.club).name,p.role,p.skill,p.agent])))};
renderAgency=c=>{ensureWorld(state);baseAgency(c);c.append(reputationPanel(),el('h2','Previsione di cassa · 8 settimane'),el('p','Include solo spese attuali, sponsor attivi e commissioni già concluse. Non presume nuovi trasferimenti.'),table(['Settimana','Incassi certi','Spese','Cassa prevista'],forecast().map(r=>[r.week,money(r.income),money(r.cost),money(r.balance)])),el('h2','Commissioni da incassare'));for(const r of state.receivables)c.append(el('p','S'+r.due+' · '+r.reason+' · '+money(r.amount)));if(!state.receivables.length)c.append(el('p','Nessun pagamento differito.'))};
