// Opportunities, conversations and negotiation intelligence.
const previousEnsure=ensureWorld,previousValid=validSave,previousOffice=renderOffice,previousClubs=renderClubs,previousOffers=renderOffers,previousWeekly=weekly,previousDetail=playerDetail;
ensureWorld=s=>{previousEnsure(s);if(!s.assignments)s.assignments=s.clubs.slice(0,4).map(c=>({id:'assignment-'+c.id,club:c.id,role:c.need,minSkill:cap(c.prestige-15,40,72),reward:6000+c.prestige*100,due:s.week+12,accepted:false,completed:false}));if(!s.debrief)s.debrief=[];for(const o of s.offers)if(!o.dossier)o.dossier={knowledge:0,notes:[],lastStage:o.stage};return s};
validSave=s=>{if(!previousValid(s))return false;if(s.assignments&&(!Array.isArray(s.assignments)||s.assignments.some(a=>!a||typeof a.id!=='string'||!s.clubs.some(c=>c.id===a.club)||!ROLES.includes(a.role)||!Number.isFinite(a.minSkill)||!Number.isFinite(a.reward)||a.reward<0||!Number.isFinite(a.due)||typeof a.accepted!=='boolean'||typeof a.completed!=='boolean')))return false;if(s.debrief&&(!Array.isArray(s.debrief)||s.debrief.some(d=>!d||typeof d.text!=='string'||!Number.isFinite(d.week))))return false;if(s.offers.some(o=>o.dossier&&(!Number.isFinite(o.dossier.knowledge)||o.dossier.knowledge<0||o.dossier.knowledge>2||!Array.isArray(o.dossier.notes)||o.dossier.notes.some(n=>typeof n!=='string'))))return false;ensureWorld(s);return true};
function acceptAssignment(a){ask('Accetta l’incarico',state.clubs[a.club].name+' cerca un '+a.role+' di qualità almeno '+a.minSkill+'. Scadenza settimana '+a.due+'. Premio '+money(a.reward)+' se concludi un nuovo accordo compatibile. 1 azione; nessuna penale economica.',()=>perform(0,()=>{a.accepted=true;log('Incarico accettato da '+state.clubs[a.club].name+'.')},'Incarico club'))}
function conversation(p){const d=el('div');d.append(el('p',p.name+': «La mia priorità è '+p.goal.toLowerCase()+'. Qual è il tuo piano?»'),el('p','Ogni risposta consuma 1 azione. Le promesse hanno una scadenza e possono danneggiare la fiducia.'),actBtn('Ascolta e definisci obiettivi · € 400',()=>{perform(400,()=>{p.trust=cap(p.trust+8,0,100);story(p,'Abbiamo discusso un piano realistico senza nuove promesse.');log('Colloquio con '+p.name+': fiducia +8.')},'Colloquio');$('modal').close()},400),actBtn('Prometti un nuovo club entro 8 settimane',()=>{perform(0,()=>{p.promises.push({kind:'Nuovo club',due:state.week+8,done:false});p.trust=cap(p.trust+12,0,100);story(p,'Mi è stato promesso un nuovo club entro la settimana '+(state.week+8)+'.')},'Promessa');$('modal').close()},0,p.promises.some(pr=>!pr.done&&pr.kind==='Nuovo club')?'Promessa già attiva':''),actBtn('Spiega che occorre pazienza',()=>{perform(0,()=>{const change=p.patience>=60?6:-6;p.trust=cap(p.trust+change,0,100);story(p,change>0?'Ho accettato di aspettare l’occasione giusta.':'Non condivido l’invito ad aspettare.');log('Colloquio: fiducia '+(change>0?'+':'')+change+'.')},'Colloquio');$('modal').close()}));ask('Colloquio personale',d,()=>{});$('confirm').textContent='Chiudi'}
playerDetail=p=>{previousDetail(p);if(state.players.some(q=>q.id===p.id))$('modalBody').append(actBtn('Parla del futuro · 1 azione',()=>conversation(p)))};
function investigate(o){perform(700,()=>{o.dossier.knowledge=Math.min(2,o.dossier.knowledge+1);const c=state.clubs[o.cid];o.dossier.notes.push(o.dossier.knowledge===1?(pRole(o)===c.need?'L’allenatore considera questo ruolo una priorità.':'Il profilo non copre il bisogno principale del club.'):'Budget attuale del club: '+money(c.budget)+'. Le risorse possono cambiare prima della firma.');log('Informazioni raccolte sulla trattativa con '+c.name+'.')},'Dossier trattativa')}
function pRole(o){return offerPlayer(o)?.role}
function dossier(o){ensureWorld(state);const p=offerPlayer(o),c=state.clubs[o.cid],d=el('div');d.append(el('p',p.name+' → '+c.name+' · '+o.type),el('p','Stato: '+['condizioni da concordare','consenso del club attuale','decisione del giocatore','firma finale'][o.stage]),el('p','Scade alla settimana '+o.expires+'. Controfferte inviate: '+o.rounds+'.'),el('p','Guadagno dell’agenzia: commissione '+o.rate+'%; 60% alla firma e 40% dopo quattro settimane.'));for(const note of o.dossier.notes)d.append(el('p',note));if(!o.dossier.notes.length)d.append(el('p','Nessuna informazione raccolta. Il gradimento del giocatore dipende da priorità, stipendio e spazio previsto.'));d.append(actBtn('Contatta una fonte · € 700',()=>{investigate(o);$('modal').close()},700,o.dossier.knowledge>=2?'Dossier completo':''));ask('Dossier della trattativa',d,()=>{});$('confirm').textContent='Chiudi'}
renderOffers=c=>{ensureWorld(state);previousOffers(c);for(const o of state.offers)c.append(btn('Dossier · '+offerPlayer(o).name,()=>dossier(o)))};
function assignmentsPanel(c){ensureWorld(state);c.append(el('h2','Incarichi dei club'));for(const a of state.assignments.filter(a=>!a.completed&&a.due>=state.week)){const d=el('article',undefined,'offer');d.append(el('h3',state.clubs[a.club].name),el('p','Cerca '+a.role+' · qualità minima '+a.minSkill+' · scadenza S'+a.due),el('p','Premio agenzia '+money(a.reward)+' · '+(a.accepted?'Incarico attivo':'Disponibile')),a.accepted?el('p','Concludi un nuovo accordo con questo club per un assistito compatibile.'):actBtn('Accetta incarico · 1 azione',()=>acceptAssignment(a)));c.append(d)}}
renderClubs=c=>{previousClubs(c);assignmentsPanel(c)};
