// Agency identity and simulated media decisions.
const strategyEnsure=ensureWorld,strategyValid=validSave,strategyAgency=renderAgency,strategyOffice=renderOffice,strategyWeekly=weekly,strategyPlayer=createPlayer,strategyChance=offerChance;
