// Player retirement and former-player mentoring.
const retirementEnsure=ensureWorld,retirementValid=validSave,retirementWeekly=weekly,retirementAgency=renderAgency,retirementDetail=playerDetail,retirementOffice=renderOffice,retirementExpenses=expenses,retirementPriority=weeklyPriorities,retirementMakeOffer=makeOffer,retirementPitch=pitchDialog;
