// Career milestones: unlocked results persist, rewards can only be collected once.
const milestoneEnsure=ensureWorld,milestoneValid=validSave,milestoneAgency=renderAgency,milestoneOffice=renderOffice,milestoneRender=render;
const MILESTONES=[{id:'first-deal',title:'Il primo accordo',rule:'Concludi almeno un contratto.',target:1,reward:2000,progress:s=>s.history.length},{id:'three-clubs',title:'Una rete di club',rule:'Concludi accordi con tre club diversi nello storico.',target:3,reward:6000,progress:s=>new Set(s.history.map(h=>h.club)).size},{id:'trusted-roster',title:'Un rapporto solido',rule:'Rappresenta contemporaneamente tre assistiti con fiducia almeno 80.',target:3,reward:3000,progress:s=>s.players.filter(p=>p.trust>=80).length},{id:'young-roster',title:'La prossima generazione',rule:'Rappresenta contemporaneamente tre giocatori fino a 21 anni.',target:3,reward:4000,progress:s=>s.players.filter(p=>p.age<=21).length},{id:'second-season',title:'L’agenzia cresce',rule:'Raggiungi la seconda stagione con la carriera ancora attiva.',target:2,reward:5000,progress:s=>s.ended?0:s.season}];
