meeting=c=>{ensureWorld(state);if(!state.clubs.includes(c)||contactBlock(c)){notice=contactBlock(c)||'Club non disponibile';render();return false}return perform(1000,()=>{c.relation=cap(c.relation+12,0,100);c.lastContact=state.week;c.contactHistory.unshift({week:state.week,relation:c.relation});c.contactHistory=c.contactHistory.slice(0,8);log('Incontro con il direttore di '+c.name+': relazione '+c.relation+'/100. Prossimo incontro da S'+(state.week+2)+'.')},'Relazioni '+c.name)};
function contactJournal(c){const d=el('div');d.append(el('p','Relazione attuale '+c.relation+'/100. Ogni incontro costa € 1.000 e una azione, aumenta la relazione di 12 punti fino a 100 e richiede due settimane prima del successivo.'));if(!c.contactHistory.length)d.append(el('p','Nessun incontro registrato. Gli incontri precedenti a questo aggiornamento non sono ricostruiti.'));for(const h of c.contactHistory)d.append(el('p','Settimana '+h.week+' · relazione dopo l’incontro '+h.relation+'/100'));ask('Diario contatti · '+c.name,d,()=>{});$('confirm').textContent='Chiudi'}
function opportunityRows(){const rows=[];for(const c of state.clubs)for(const p of state.players.filter(p=>p.role===c.need&&p.club!==c.id)){const reason=p.retireAt?'Ritiro annunciato':p.loan?'Prestito in corso':p.cooldown>state.week?'Nuova operazione dalla settimana '+p.cooldown:p.club!==null&&!marketOpen()?'Finestra di mercato chiusa':state.offers.some(o=>o.pid===p.id&&o.cid===c.id)?'Trattativa già aperta':'';rows.push({p,c,reason})}return rows.sort((a,b)=>Number(!!a.reason)-Number(!!b.reason)||b.c.relation-a.c.relation)}
function opportunitiesDialog(){const d=el('div'),rows=opportunityRows();d.append(el('p','Corrispondenze fra ruolo principale degli assistiti e bisogno attuale dei club. Il budget, le condizioni e i consensi si verificano durante la proposta: questa lista non garantisce un accordo.'));if(!rows.length)d.append(el('p','Nessun assistito copre al momento i ruoli richiesti da altri club.'));for(const {p,c,reason}of rows){const row=el('article',undefined,'offer');row.append(el('h3',p.name+' → '+c.name),el('p',p.role+' · relazione '+c.relation+'/100 · budget '+money(c.budget)),el('p',reason||'Ruolo richiesto: puoi valutare una proposta.'),btn('Apri scheda assistito',()=>{$('modal').close();playerDetail(p)}));d.append(row)}ask('Opportunità per gli assistiti',d,()=>{});$('confirm').textContent='Chiudi'}
renderClubs=c=>{contactClubs(c);c.append(el('h2','La tua rete di contatti'),el('p','Gli incontri con lo stesso dirigente richiedono due settimane di attesa. Consultare diario e opportunità è gratuito.'),btn('Opportunità per gli assistiti',opportunitiesDialog));for(const club of [...state.clubs].sort((a,b)=>b.relation-a.relation))c.append(el('p',club.name+' · relazione '+club.relation+'/100 · ultimo incontro '+(club.lastContact===null?'non registrato':'S'+club.lastContact)+(contactBlock(club)?' · '+contactBlock(club):'')),btn('Diario · '+club.name,()=>contactJournal(club)))};
if(typeof document!=='undefined')boot();
